use vlajmaji::lexicon::*;
use vlajmaji::search::{DictionarySearchEngine, DictionaryExactOptions, ReferenceStatus};
use sha2::{Digest,Sha256};
fn sha(x:&[u8])->String {format!("{:x}",Sha256::digest(x))}
fn gismu()->String {let mut row=vec![b' ';158];for (start,s) in [(1,"farvi"),(7,"fav"),(20,"growth"),(62,"x1 develops into x2")] {row[start..start+s.len()].copy_from_slice(s.as_bytes());}String::from_utf8(row).unwrap()}
fn cmavo(class:&str)->String {format!("{:<10}{:<10}{:<41}{}",".a",class,"logical or","sumti connective")}
fn import(g:&[u8],c:&[u8],r:&[u8],n:&[u8])->LlgImport {let o=LlgImportOptions{expected_gismu_sha256:sha(g),expected_cmavo_sha256:sha(c),expected_rafsi_sha256:sha(r),expected_notice_sha256:sha(n),base_locator:"https://example.invalid/synthetic".into()};import_llg_lists(g,c,r,n,&o).unwrap()}
fn synthetic_lensisku()->Dictionary {
 let raw=br#"[{"word":"farvi","word_type":"gismu","definition":"synthetic alternative one"},{"word":"farvi","word_type":"gismu","definition":"synthetic alternative two"}]"#;
 let meta=format!("language_tag = \"en\"\nlanguage_realname = \"English\"\nsource_language_tag = \"jbo\"\nformat = \"json\"\npositive_scores_only = false\nfilename = \"dictionary-en.json\"\nmetadata_url = \"https://example.invalid/languages\"\ndownload_url = \"https://example.invalid/synthetic-export\"\nlensisku_created_at = \"2026-10-04T03:07:08Z\"\nsha256 = \"{}\"\ndefinition_count = 2\nentry_count = 1\n",sha(raw));
 import_jbotci_export(raw,meta.as_bytes(),&JbotciImportOptions{revision:"0".repeat(40),expected_raw_sha256:sha(raw),expected_metadata_sha256:sha(meta.as_bytes())}).unwrap().into_dictionary()
}
fn main(){
 let g=gismu();let c=cmavo("A");let rafsi=b"fav farvi  growth\n";let notice=b"Explicit synthetic source notice\n";
 let baseline=import(format!("{g}\n").as_bytes(),format!("{c}\n").as_bytes(),rafsi,notice).into_dictionary();assert_eq!((baseline.metadata().assertions.len(),baseline.metadata().entries.len(),baseline.metadata().forms.len(),baseline.metadata().contexts.len()),(3,2,2,3));
 let duplicate=import(format!("{g}\n{g}\n").as_bytes(),format!("{c}\n").as_bytes(),rafsi,notice).into_dictionary();assert_eq!((duplicate.metadata().assertions.len(),duplicate.metadata().forms.len()),(4,3));assert_ne!(duplicate.metadata().assertions[0].occurrence,duplicate.metadata().assertions[1].occurrence);
 let header=import(format!("00000 Lojban synthetic\n{g}\n").as_bytes(),format!("00001 Lojban synthetic\n{c}\n").as_bytes(),rafsi,notice);assert_eq!(header.dictionary().metadata().assertions.len(),5);let hr=serde_json::to_value(header.report()).unwrap();assert_eq!(hr["components"][0]["declared_count_matches"],false);assert_eq!(hr["components"][1]["declared_count_matches"],true);
 let bare=import(format!("{g}\r").as_bytes(),format!("{c}\n").as_bytes(),rafsi,notice).into_dictionary();let cap=bare.captures().iter().find(|x|x.identity.namespace=="captured:llg:gismu").unwrap();assert_eq!(cap.occurrences[0].raw_line.as_deref(),Some(format!("{g}\r").as_str()));
 let crlf=import(format!("{g}\r\n").as_bytes(),format!("{c}\r\n").as_bytes(),b"fav farvi  growth\r\n",notice).into_dictionary();assert_eq!(crlf.captures().iter().find(|x|x.identity.namespace=="captured:llg:gismu").unwrap().occurrences[0].raw_line.as_deref(),Some(g.as_str()));
 for (name,extra) in [("blank",""),("separator","-----"),("nonascii","é")]{let d=import(format!("{g}\n{extra}\n").as_bytes(),format!("{c}\n").as_bytes(),rafsi,notice).into_dictionary();assert_eq!(d.metadata().assertions.len(),4,"{name}");assert_eq!(d.metadata().assertions.iter().filter(|a|matches!(a.eligibility,Eligibility::Excluded{..})).count(),2,"{name}");let cap=d.captures().iter().find(|x|x.identity.namespace=="captured:llg:gismu").unwrap();assert_eq!(cap.occurrences[1].raw_line.as_deref(),Some(extra));}
 let conflicting=import(format!("{g}\n").as_bytes(),format!("{c}\n{}\n",cmavo("BAI")).as_bytes(),rafsi,notice).into_dictionary();let entry=conflicting.metadata().entries.iter().find(|e|e.spelling==Presence::Value(".a".into())).unwrap();assert_eq!(entry.selmaho,Presence::Missing);assert!(conflicting.metadata().releases.iter().flat_map(|r|&r.diagnostics).any(|d|d.code=="conflicting_cmavo_classes"));
 let gg=format!("{g}\n");let cc=format!("{c}\n");let options=LlgImportOptions{expected_gismu_sha256:sha(gg.as_bytes()),expected_cmavo_sha256:sha(cc.as_bytes()),expected_rafsi_sha256:sha(rafsi),expected_notice_sha256:sha(notice),base_locator:"https://example.invalid/synthetic".into()};let mut wrong=options.clone();wrong.expected_rafsi_sha256="0".repeat(64);assert!(matches!(import_llg_lists(gg.as_bytes(),cc.as_bytes(),rafsi,notice,&wrong),Err(LlgImportError::HashMismatch{..})));let mut wrong=options.clone();wrong.base_locator="\n".into();assert!(matches!(import_llg_lists(gg.as_bytes(),cc.as_bytes(),rafsi,notice,&wrong),Err(LlgImportError::InvalidOptions(_))));let bad=b"\xff";let mut utf=options;utf.expected_notice_sha256=sha(bad);assert!(matches!(import_llg_lists(gg.as_bytes(),cc.as_bytes(),rafsi,bad,&utf),Err(LlgImportError::InvalidUtf8{..})));
 println!("PASS independent public synthetic native-line/class/optional-tail/multiplicity/header/pin/UTF8 controls");
 assert_eq!(vlajmaji_data_llg::release_bytes(),vlajmaji::data_llg::release_bytes());assert_eq!(vlajmaji_data_llg::seal_bytes(),vlajmaji::data_llg::seal_bytes());let seal=PackSeal::from_json_bytes(vlajmaji_data_llg::seal_bytes()).unwrap();assert_eq!(seal.payload_kind,PackPayloadKind::Full);assert_eq!(seal.release_sha256,sha(vlajmaji_data_llg::release_bytes()));let llg=vlajmaji::data_llg::load().unwrap();let m=llg.metadata();assert_eq!((m.entries.len(),m.assertions.len(),m.forms.len(),m.contexts.len(),m.extensions.len()),(2435,4074,3091,5804,2865));assert_eq!(llg.captures().len(),4);println!("PASS Full embedded direct/umbrella bytes, strict load and full native-derived populations");
 let header=m.assertions.iter().find(|a|a.occurrence.capture.namespace=="captured:llg:gismu"&&a.occurrence.locator=="1").unwrap().clone();let release=m.releases.iter().find(|r|r.assertions.contains(&header.id)).unwrap().id.clone();
 let combined=compose_dictionaries(vec![llg,synthetic_lensisku()]).unwrap();assert_eq!((combined.registry().as_document().sources.len(),combined.metadata().entries.len(),combined.metadata().assertions.len(),combined.metadata().forms.len()),(2,2437,4076,3091));
 let bytes=combined.to_json_bytes().unwrap();let path=std::path::Path::new("/tmp/vlajmaji-p01-a03-cdc/s02/composed-store01");let e=DictionarySearchEngine::build(path,&bytes).unwrap();drop(e);let s=vlajmaji::store::DictionaryStore::open(path).unwrap();assert_eq!(s.dictionary().unwrap(),combined);drop(s);let e=DictionarySearchEngine::open(path).unwrap();let opts=DictionaryExactOptions::default();let all=e.exact("farvi",opts).unwrap();assert_eq!((all.totals.occurrences,all.totals.distinct_spellings,all.totals.source_groups),(3,1,2));
 for (source,n) in [("llg",1),("LLG",1),("lensisku",2),("LSK",2)]{let x=e.exact("farvi",DictionaryExactOptions{sources:vec![source.into()],..Default::default()}).unwrap();assert_eq!(x.totals.occurrences,n);assert_eq!(x.groups.len(),1);if source=="llg" {assert_eq!(x.groups[0].hits[0].forms.len(),2);assert!(x.groups[0].hits[0].forms.iter().all(|f|f.kind==FormKind::AssignedRafsi));}}
 let expected:Vec<_>=all.groups.iter().flat_map(|g|g.hits.iter().map(|h|h.assertion.id.clone())).collect();let mut paged=Vec::new();let mut cursor=None;for _ in 0..3 {let x=e.exact("farvi",DictionaryExactOptions{page_size:Some(1),cursor,..Default::default()}).unwrap();assert_eq!(x.totals,all.totals);paged.extend(x.groups.iter().flat_map(|g|g.hits.iter().map(|h|h.assertion.id.clone())));cursor=x.next_cursor;}assert!(cursor.is_none());assert_eq!(paged,expected);
 let resolved=e.resolve(&RelationTarget::Catalog(CatalogTarget{source:SourceId::new("llg").unwrap(),release,native_entry_id:None,native_assertion_id:None,occurrence:Some(header.occurrence)})).unwrap();assert_eq!(resolved.status,ReferenceStatus::Resolved);assert_eq!(resolved.confirmed.len(),1);assert!(resolved.confirmed[0].payload_present);assert!(!resolved.confirmed[0].current_eligible);assert!(resolved.confirmed[0].raw.is_some());assert_eq!(e.resolve(&RelationTarget::Unknown).unwrap().status,ReferenceStatus::Unknown);assert_eq!(e.exact("PROJECT03_ABSENT",DictionaryExactOptions::default()).unwrap().totals.occurrences,0);assert!(e.exact("farvi",DictionaryExactOptions{sources:vec!["unknown".into()],..Default::default()}).is_err());
 println!("PASS consumed Full LLG+tiny Lensisku composition/create/reopen/source grouping/totals/3pages/header raw reference/absence; no topology choice");
}
